      SUBROUTINE PIVENTCC     COORDINATE TRANSFORMATION AT SECTION ENTRANCEC     (USED FOR MISALIGNMENTS)CC ----------------------------------------------------------------------      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'ELM8A.CIN'      INCLUDE 'ELM8D.CIN'CC     LOCAL VARIABLESC      INTEGER         J, K      REAL            COSA, COST, S, SINA, SINT, XNORMC-------------------------------------------------------------------------------C      IF (CHORD) GO TO 100      DO 10 J = 1, 3      DO 10 K = 1, 3      OT(J,K) = 0.0   10 CONTINUE      DO 20 J = 1, 3      OT(J,J) = 1.0   20 CONTINUE      DO 30 J = 1, 3   30 XT(J) = 0.0C      IF (TMK .EQ. 0) GO TO 200      IF (TMK .EQ. 2) GO TO 50      S = 0.0      DO 40 J = 1, 3      S = S + XR(J)**2   40 CONTINUE      XT(3) = -0.5*S/XR(3)      GO TO 200C   50 DO 55 J = 1, 3      XT(J) = - XR(J)   55 CONTINUE      DO 60 J = 1, 3      DO 60 K = 1, 3      OT(J,K) = OR(K,J)   60 CONTINUE      GO TO 200CC     MISALIGNMENT ABOUT CHORD OF BENDING MAGNETC  100 S = 0.0      DO 112 J = 1, 3      S = S + XR(J)**2  112 CONTINUE      XNORM = SQRT(S)      DO 115 J = 1, 3      OT(J,3) = XR(J)/XNORM  115 CONTINUE      OT(3,1) = - OT(1,3)      OT(3,2) = - OT(2,3)      SINA = SQRT(OT(1,3)**2 + OT(2,3)**2)      COSA = OT(3,3)      IF (SINA .EQ. 0.0) THEN        COST = 1.0        SINT = 0.0      ELSE        COST = OT(1,3)/SINA        SINT = OT(2,3)/SINA      ENDIF      OT(1,1) = COST**2*COSA + SINT**2      OT(1,2) = COST*SINT*(COSA - 1.0)      OT(2,1) = OT(1,2)      OT(2,2) = SINT**2*COSA + COST**2      IF (TMK .EQ. 1) THEN        DO 150 J = 1, 3  150   XT(J) = - 0.5*XR(J)      ELSE IF (TMK .EQ. 2) THEN        DO 160 J = 1, 3  160   XT(J) = - XR(J)      ENDIFC  200 RETURN      END